  document.addEventListener('click',e=>{const b=e.target.closest('[data-shopping-refresh],[data-shopping-cancel],[data-shopping-edit-account],[data-shopping-login]');if(!b)return;if(b.hasAttribute('data-shopping-login')){document.getElementById('cartModal').classList.remove('open');sessionStorage.setItem('mio-resume-shopping','1');go('login');return}if(b.hasAttribute('data-shopping-edit-account')){const a=adminData.accounts.find(a=>a.id===b.dataset.shoppingEditAccount),f=document.getElementById('shoppingBankForm');for(const [key,value]of Object.entries({id:a.id,bank:a.bank_name,title:a.account_title,number:a.account_number,instructions:a.instructions}))f.elements[key].value=value;f.elements.active.checked=a.active;document.getElementById('shoppingBankFormTitle').textContent='Edit receiving account';f.scrollIntoView({block:'center',behavior:'smooth'});return}submit({querySelector:()=>b},async()=>{if(b.dataset.shoppingCancel)await rpc('cancel_unpaid_order',{p_order_id:b.dataset.shoppingCancel});await refresh()})});
  document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('.shopping-payment-form,.shopping-review-form,.shopping-refund-form,.shopping-profile-form,#shoppingBankForm,#shoppingMembership'))return;e.preventDefault();submit(f,async()=>{const v=f.elements;if(f.matches('.shopping-payment-form')){const file=v.proof.files?.[0];if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size<1||file.size>5242880)throw Error('Choose a JPG, PNG or WebP payment screenshot up to 5 MB');const signature=[file.name,file.size,file.lastModified].join(':');if(f.dataset.proofSignature!==signature){const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type],path=getSession().user.id+'/'+f.dataset.id+'/'+crypto.randomUUID()+'.'+ext;const {error}=await db.storage.from('customer-payment-proofs').upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;f.dataset.proofPath=path;f.dataset.proofSignature=signature;}await rpc('submit_shopping_advance_with_proof',{p_order_id:f.dataset.id,p_account_id:v.account.value,p_transaction_id:v.transaction.value.trim(),p_proof_path:f.dataset.proofPath});}else if(f.matches('.shopping-review-form'))await rpc('admin_review_shopping_advance',{p_order_id:f.dataset.id,p_approve:v.approve.value==='true',p_verified_pkr:v.amount.value?Number(v.amount.value):null,p_note:v.note.value.trim()});else if(f.matches('.shopping-refund-form'))await rpc('admin_record_shopping_refund',{p_order_id:f.dataset.id,p_reference:v.reference.value.trim()});else if(f.id==='shoppingBankForm')await rpc('admin_save_shopping_payment_account',{p_id:v.id.value||null,p_bank:v.bank.value,p_title:v.title.value,p_number:v.number.value,p_instructions:v.instructions.value,p_active:v.active.checked});else if(f.id==='shoppingMembership'){await rpc('join_network_from_shopping',{p_referral_code:v.referral.value,p_consent:v.consent.checked});await refreshIdentity();go('dashboard');toast('Membership created. Your shopping history is preserved.');return}else{await rpc('save_shopping_profile',{p_name:v.full_name.value,p_phone:v.phone.value,p_country:v.country.value,p_address:v.address.value,p_city:v.city.value,p_consent:identity?.terms_accepted||v.consent?.checked||false});await identify(getSession())}toast('Saved successfully');if(f.closest('#adminShoppingPayments'))await admin();else await refresh()})});
  document.addEventListener('click',e=>{const close=e.target.closest('[data-shopping-auth-close]'),mode=e.target.closest('[data-shopping-auth-mode]'),reset=e.target.closest('[data-shopping-password-reset]');if(close)closeAuth();if(mode)setAuthMode(mode.dataset.shoppingAuthMode);if(reset)submit({querySelector:()=>reset},async()=>{const email=identity?.email||getSession()?.user.email;if(!email)throw Error('Sign in again to verify your email');const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname+'#reset'});if(error)throw error;document.getElementById('shoppingPasswordStatus').textContent='Password reset link sent. Check your email.'})});
  dialog.addEventListener('cancel',()=>{dialog.querySelector('[name="password"]').value=''});
  document.getElementById('shoppingAuthForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{const v=form.elements,status=document.getElementById('shoppingAuthStatus');status.textContent='';try{const data=await authenticate({mode:authContext.mode,name:v.full_name.value,phone:v.phone.value,email:v.email.value,password:v.password.value,affiliate:authContext.affiliate,consent:v.consent.checked});v.password.value='';if(!data.session){status.textContent='Check your email to verify your User account, then sign in here to resume checkout. If you already have an account, choose Sign in.';return}closeAuth();toast('Account ready. Your checkout is waiting.')}catch(error){status.textContent=error.message;throw error}})});
  document.addEventListener('submit',e=>{if(e.target.id!=='shoppingEmailForm')return;e.preventDefault();const form=e.target;submit(form,async()=>{const {error}=await db.auth.updateUser({email:form.elements.email.value.trim()},{emailRedirectTo:location.origin+location.pathname+'#account/settings'});if(error)throw error;form.querySelector('[role="status"]').textContent='Check your current and new email inboxes to confirm this change.'})});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-shopping-proof]');if(!b)return;submit({querySelector:()=>b},async()=>{const {data,error}=await db.storage.from('customer-payment-proofs').createSignedUrl(b.dataset.shoppingProof,300);if(error)throw error;let proof=document.getElementById('shoppingProofDialog');if(!proof){proof=document.createElement('dialog');proof.id='shoppingProofDialog';proof.className='shopping-proof-dialog';proof.innerHTML='<form method="dialog"><button class="btn" type="submit">Close screenshot</button></form><img alt="Payment screenshot">';document.body.append(proof)}proof.querySelector('img').src=data.signedUrl;if(proof.showModal)proof.showModal();else proof.setAttribute('open','');})});
